import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "रिपोर्ट में कप्पा और लैम्डा लिखा है? या कप्पा लैम्डा रेशियो? सीरम फ्री लाइट चेन टेस्ट क्या है, और यह रेशियो क्या बताता है, आखिर तक देखिए.",
 "हमारी हर एंटीबॉडी, वाई के आकार की होती है. इसमें दो भारी चेन, और दो हल्की चेन होती हैं. हल्की चेन, यानी लाइट चेन, दो तरह की होती हैं. कप्पा और लैम्डा.",
 "प्लाज़्मा सेल, ज़रूरत से थोड़ी ज़्यादा लाइट चेन बनाते हैं. जो चेन एंटीबॉडी से जुड़ी नहीं होतीं, वे खून में आज़ाद घूमती हैं. इन्हें फ्री लाइट चेन कहते हैं. यह टेस्ट खून में फ्री कप्पा, और फ्री लैम्डा, दोनों की मात्रा मापता है.",
 "असली बात है रेशियो, यानी कप्पा को लैम्डा से भाग देना. सामान्य हालत में दोनों एक संतुलन में रहते हैं. एक आम रेफरेंस रेंज है, शून्य दशमलव दो छह से, एक दशमलव छह पांच तक. पर यह रेंज लैब और मशीन के हिसाब से अलग हो सकती है.",
 "अगर प्लाज़्मा सेल का एक ही समूह बेकाबू हो जाए, तो वह सिर्फ एक तरह की लाइट चेन, बहुत ज़्यादा बनाता है. तब संतुलन बिगड़ जाता है. कप्पा ज़्यादा हो, तो रेशियो ऊपर जाता है. लैम्डा ज़्यादा हो, तो रेशियो नीचे.",
 "यह टेस्ट क्यों ज़रूरी है? लगभग पंद्रह प्रतिशत मल्टीपल मायलोमा में, सिर्फ लाइट चेन बनती है, और प्रोटीन इलेक्ट्रोफोरेसिस अक्सर सामान्य आता है. ऐसे में फ्री लाइट चेन टेस्ट, बीमारी पकड़ने में मदद करता है. इसलिए डॉक्टर अक्सर इसे, एस पी ई पी और इम्यूनोफिक्सेशन के साथ करवाते हैं.",
 "किडनी का ध्यान रखें. फ्री लाइट चेन किडनी से साफ होती हैं. किडनी कमज़ोर हो, तो कप्पा और लैम्डा दोनों बढ़ सकते हैं, और रेशियो भी थोड़ा ऊपर जा सकता है. इसलिए किडनी की बीमारी में, डॉक्टर अलग रेंज से रिपोर्ट देखते हैं.",
 "यह टेस्ट मायलोमा की पहचान में, इलाज के दौरान बीमारी पर नज़र रखने में, और एम जी यू एस जैसी स्थिति में खतरे का अंदाज़ा लगाने में मदद करता है. बहुत ज़्यादा असंतुलित रेशियो, डॉक्टर के लिए एक अहम संकेत होता है.",
 "तैयारी. बस खून का एक सैंपल. आमतौर पर खाली पेट की ज़रूरत नहीं, फिर भी लैब के निर्देश मानें. रिपोर्ट में कप्पा, लैम्डा, और रेशियो लिखे होते हैं. एक अकेली रिपोर्ट से नतीजा न निकालें. डॉक्टर इसे दूसरी जांचों के साथ देखते हैं.",
 close_voice("क्या आपकी रिपोर्ट में कभी कप्पा लैम्डा रेशियो आया है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/flcr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/flc_{i}.wav"],check=True); f=f"/tmp/flc_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/flc_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
